import { defineConfig } from 'vite';
import fs from 'node:fs';
import path from 'node:path';

// Serve audio from OUTSIDE the repo. Never copy audio into the repo (CLAUDE.md rule 1).
//   /fixtures/*  -> ./fixtures (gitignored, generated by scripts/make-fixtures.sh)
//   /audio/*     -> $AUDIO_DIR (e.g. ~/Music/GarageBand/ward-choir/candelight-carol/encoded)
const roots: Record<string, string | undefined> = {
  '/fixtures/': path.resolve('fixtures'),
  '/audio/': process.env.AUDIO_DIR,
};
const mime: Record<string, string> = { '.m4a': 'audio/mp4', '.wav': 'audio/wav', '.aif': 'audio/aiff' };

export default defineConfig({
  server: { host: true, headers: { 'Cross-Origin-Resource-Policy': 'same-origin' } },
  plugins: [{
    name: 'external-audio',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        const url = decodeURIComponent((req.url ?? '').split('?')[0]);
        for (const [prefix, root] of Object.entries(roots)) {
          if (!url.startsWith(prefix)) continue;
          if (!root) { res.statusCode = 404; return res.end('AUDIO_DIR not set'); }
          const file = path.resolve(root, url.slice(prefix.length));
          if (!file.startsWith(root + path.sep) || !fs.existsSync(file)) { res.statusCode = 404; return res.end('not found'); }
          const size = fs.statSync(file).size;
          const type = mime[path.extname(file)] ?? 'application/octet-stream';
          const range = /bytes=(\d*)-(\d*)/.exec(req.headers.range ?? '');
          if (range) { // Safari <audio> needs Range support
            const s = range[1] ? +range[1] : 0, e = range[2] ? +range[2] : size - 1;
            res.writeHead(206, { 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Content-Range': `bytes ${s}-${e}/${size}`, 'Content-Length': e - s + 1 });
            return fs.createReadStream(file, { start: s, end: e }).pipe(res);
          }
          res.writeHead(200, { 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Content-Length': size });
          return fs.createReadStream(file).pipe(res);
        }
        next();
      });
    },
  }],
});
